from typing import List

class Solution:
    def stringHash(self, s: str, k: int) -> str:
        n = len(s)
        res: List[str] = []
        for i in range(0, n, k):
            substr = s[i:i+k]
            total = sum(ord(c) - ord('a') for c in substr)
            hashed = total % 26
            res.append(chr(ord('a') + hashed))
        return "".join(res)

