class Solution:
    def smallestNumber(self, n: int) -> int:
        # Return n if it already consists solely of set bits
        if n & (n + 1) == 0:
            return n
        # Otherwise find the smallest k such that 2^k - 1 >= n
        k = n.bit_length()
        return (1 << k) - 1

