class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        vowels = set('aeiou')
        vowel_count = [0] * 5  # a, e, i, o, u
        vowel_map = {'a':0, 'e':1, 'i':2, 'o':3, 'u':4}
        cons = 0
        l = 0
        total = 0

        # helper to check all vowels present
        def all_vowels():
            return all(c > 0 for c in vowel_count)

        for r in range(n):
            ch = word[r]
            if ch in vowels:
                idx = vowel_map[ch]
                vowel_count[idx] += 1
            else:
                cons += 1

            # shrink from left while consonants > k
            while cons > k and l <= r:
                ch_left = word[l]
                if ch_left in vowels:
                    idx = vowel_map[ch_left]
                    vowel_count[idx] -= 1
                else:
                    cons -= 1
                l += 1

            # after shrinking, check if conditions satisfied
            if cons == k and all_vowels():
                total += 1

        return total
