class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(st: str) -> List[str]:
            n = len(st)
            res = []
            for i in range(n + 1):          # allow empty prefix
                for j in range(i, n + 1):  # j can be n to include up to end
                    if i == j:
                        res.append('')     # empty substring
                    else:
                        res.append(st[i:j])
            return res

        subs_s = substrings(s)
        subs_t = substrings(t)

        best = 0
        for a in subs_s:
            for b in subs_t:
                cand = a + b
                if cand == cand[::-1]:
                    if len(cand) > best:
                        best = len(cand)
        return best
